mapper.select:
SELECT u.user_id, u.user_name, u.user_type, u.nick_name, u.tenant_id, st.tenant_name, d.INDUSTRY_CODE, d.app_ver_code, ic.industry_name, fu.dispatch_desk_num, fu.mobile_terminal_num, fu.id as communicationId, fu.update_user, fu.update_time as updateTime FROM sys_user u LEFT JOIN ( WITH RECURSIVE cte AS ( SELECT 1 AS n UNION ALL SELECT n + 1 FROM cte WHERE n < 50 ) SELECT u2.user_id, SUBSTRING_INDEX(SUBSTRING_INDEX(u2.DEPT_ID, ',', cte.n), ',', -1) AS dept_id FROM sys_user u2 JOIN cte ON cte.n <= (LENGTH(u2.DEPT_ID) - LENGTH(REPLACE(u2.DEPT_ID, ',', '')) + 1) WHERE u2.DEL_FLAG = 0 ) ud ON u.user_id = ud.user_id LEFT JOIN sys_dept d ON ud.dept_id = d.DEPT_ID AND d.del_flag = '0' LEFT JOIN sys_tenant_info st ON u.tenant_id = st.tenant_id LEFT JOIN sys_industry_conf ic ON ic.industry_code = d.INDUSTRY_CODE AND ic.delete_flag = 0 LEFT JOIN vm_fusion_communication_t fu ON fu.USER_ID = u.USER_ID where u.DEL_FLAG = 0
and u.user_Name like CONCAT(CONCAT('%', #{userName}),'%')
and u.nick_name like CONCAT(CONCAT('%', #{nickName}),'%')
and fu.dispatch_Desk_Num = #{dispatchDeskNum}
and fu.mobile_Terminal_Num = #{mobileTerminalNum}
and fu.update_User like CONCAT(CONCAT('%', #{updateUser}),'%')
AND DATE_FORMAT(fu.update_Time,'%Y-%m-%d %H:%i:%s') >= #{updateStartTime}
AND DATE_FORMAT(fu.update_Time,'%Y-%m-%d %H:%i:%s') <= #{updateEndTime}
${dataScope}
order by u.create_time DESC
order by fu.update_time DESC,u.create_time DESC
order by ISNULL(fu.update_time),fu.update_time asc,u.create_time DESC

mapper.update:
UPDATE vm_fusion_communication_t
SET dispatch_desk_num   = #{dispatchDeskNum},
    mobile_terminal_num = #{mobileTerminalNum},
    update_Time         = #{updateTime},
    update_User         = #{updateUser}
WHERE user_id = #{userId}
